effect.shader:
void main(){
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 b = vec3(0.0);
    for(int i=0;i<12;i++){
        float a = float(i)/12.0*6.28318;
        vec2 o = vec2(cos(a),sin(a))*radius;
        vec3 s = texture2DCv(inputImg.texture, acScreenNorm+o).rgb;
        b += max(s - threshold, 0.0);
    }
    b /= 12.0;
    gl_FragColor = vec4(src.rgb + b*intensity, src.a);
}
